"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { CircleCheckIcon } from "@/components/blocks/parts/icons";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { ConfigureView } from "./agent-builder/configure-view";
import { FILES, INSTRUCTIONS, MODELS, NEXT_FILES, type BuilderFile, type ToolId } from "./agent-builder/data";
import { NameField } from "./agent-builder/name-field";
import { TestChat } from "./agent-builder/test-chat";
import { useInterval } from "./lib/timers";

type View = "configure" | "test";

const VIEWS: { value: View; label: string }[] = [
  { value: "configure", label: "Configure" },
  { value: "test", label: "Test" },
];

const START_TOOLS: ToolId[] = ["diary", "records", "inbox"];

/**
 * Sets up one agent: its name, model, instructions, tools and knowledge files.
 * Test swaps the form for a chat in the same box, so the card keeps its size.
 * Publish ships the setup, and the footer says whether there are unsaved changes.
 */
export function AgentBuilder({ className }: { className?: string }) {
  const [name, setName] = useState("Booking helper");
  const [view, setView] = useState<View>("configure");
  const [model, setModel] = useState(MODELS[0]!.id);
  const [instructions, setInstructions] = useState(INSTRUCTIONS);
  const [tools, setTools] = useState(() => new Set<ToolId>(START_TOOLS));
  const [files, setFiles] = useState<BuilderFile[]>(FILES);
  const [added, setAdded] = useState(0);
  const [version, setVersion] = useState(3);
  const [dirty, setDirty] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const publishTimer = useRef<number | null>(null);

  useEffect(() => () => {
    if (publishTimer.current !== null) window.clearTimeout(publishTimer.current);
  }, []);

  const uploading = files.some((file) => file.progress < 100);
  useInterval(() => {
    setFiles((list) => list.map((file) => (file.progress < 100 ? { ...file, progress: Math.min(100, file.progress + 7) } : file)));
  }, uploading ? 110 : null);

  // Every edit marks the setup unsaved until the next publish.
  const edit = <T,>(set: (value: T) => void) => (value: T) => {
    set(value);
    setDirty(true);
  };

  const toggleTool = (tool: ToolId, on: boolean) => {
    setTools((current) => {
      const next = new Set(current);
      if (on) next.add(tool);
      else next.delete(tool);
      return next;
    });
    setDirty(true);
  };

  const nextFile = NEXT_FILES[added];
  const addFile = nextFile
    ? () => {
        setFiles((list) => [...list, { ...nextFile, progress: 0 }]);
        setAdded((count) => count + 1);
        setDirty(true);
      }
    : null;

  const removeFile = (id: string) => {
    setFiles((list) => list.filter((file) => file.id !== id));
    setDirty(true);
  };

  const publish = () => {
    setPublishing(true);
    publishTimer.current = window.setTimeout(() => {
      publishTimer.current = null;
      setPublishing(false);
      setDirty(false);
      setVersion((current) => current + 1);
    }, 900);
  };

  const fade = (shown: boolean) => ({
    initial: false as const,
    animate: { opacity: shown ? 1 : 0, y: shown || reduceMotion ? 0 : 4 },
    transition: { duration: reduceMotion ? 0 : 0.2, ease: [0.2, 0, 0, 1] as const },
  });

  const status = publishing ? "Publishing" : uploading ? "Uploading files" : dirty ? "Unsaved changes" : `Version ${version} is live`;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-2xl", className)}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 flex-col">
          <NameField name={name} onRename={edit(setName)} headingId={titleId} />
          <p className="text-sm text-muted-foreground">Front desk team, version {version}</p>
        </div>
        <SegmentedControl aria-label="View" options={VIEWS} value={view} onValueChange={setView} />
      </header>

      <div className="grid h-168 @lg:h-152">
        <motion.div
          {...fade(view === "configure")}
          inert={view !== "configure"}
          aria-hidden={view !== "configure"}
          className={cn("col-start-1 row-start-1 min-h-0 overflow-y-auto scroll-fade-effect-y scrollbar-none", view === "configure" ? "z-10" : "pointer-events-none")}
        >
          <ConfigureView
            model={model}
            onModel={edit(setModel)}
            instructions={instructions}
            onInstructions={edit(setInstructions)}
            tools={tools}
            onToggleTool={toggleTool}
            files={files}
            onAddFile={addFile}
            onRemoveFile={removeFile}
          />
        </motion.div>
        <motion.div
          {...fade(view === "test")}
          inert={view !== "test"}
          aria-hidden={view !== "test"}
          className={cn("col-start-1 row-start-1 min-h-0", view === "test" ? "z-10" : "pointer-events-none")}
        >
          <TestChat agentName={name} tools={tools} />
        </motion.div>
      </div>

      <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
        <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground">
          {dirty || publishing || uploading ? (
            <span aria-hidden="true" className="size-2 rounded-full bg-chart-5" />
          ) : (
            <CircleCheckIcon aria-hidden="true" className="size-4 text-marketing-green-ink" />
          )}
          {status}
        </p>
        <Button onClick={publish} disabled={!dirty || publishing || uploading}>
          {publishing ? "Publishing" : "Publish"}
        </Button>
      </footer>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

