import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { useId } from "react";

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { formatCount } from "../lib/format";
import { INSTRUCTIONS_LIMIT, MODELS, type BuilderFile, type ToolId } from "./data";
import { FileList } from "./file-list";
import { ToolList } from "./tool-list";

/** Props for the setup form. */
export interface ConfigureViewProps {
  model: string;
  onModel: (model: string) => void;
  instructions: string;
  onInstructions: (text: string) => void;
  tools: Set<ToolId>;
  onToggleTool: (tool: ToolId, on: boolean) => void;
  files: BuilderFile[];
  onAddFile: (() => void) | null;
  onRemoveFile: (id: string) => void;
}

/** The setup form: the model, the instructions with a character count, the tool switches and the knowledge files. */
export function ConfigureView(props: ConfigureViewProps) {
  const { model, onModel, instructions, onInstructions } = props;
  const chosen = MODELS.find((item) => item.id === model) ?? MODELS[0]!;
  const id = useId();
  const nearLimit = instructions.length > INSTRUCTIONS_LIMIT * 0.9;

  return (
    <div className="flex flex-col gap-5 p-5">
      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2">
        <div className="flex min-w-0 flex-col">
          <label htmlFor={`${id}-model`} className="text-sm font-medium">
            Model
          </label>
          <span className="text-xs text-muted-foreground">{chosen.line}</span>
        </div>
        <Select value={model} onValueChange={onModel}>
          <SelectTrigger id={`${id}-model`} className="w-48">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {MODELS.map((item) => (
              <SelectItem key={item.id} value={item.id}>
                {item.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex items-baseline justify-between gap-3">
          <label htmlFor={`${id}-instructions`} className="text-sm font-medium">
            Instructions
          </label>
          <span id={`${id}-count`} className={cn("text-xs tabular-nums", nearLimit ? "text-marketing-amber-ink" : "text-muted-foreground")}>
            {formatCount(instructions.length)} of {formatCount(INSTRUCTIONS_LIMIT)}
          </span>
        </div>
        <Textarea
          id={`${id}-instructions`}
          aria-describedby={`${id}-count`}
          value={instructions}
          maxLength={INSTRUCTIONS_LIMIT}
          onChange={(event) => onInstructions(event.target.value)}
          className="max-h-40 min-h-28 resize-none"
        />
      </div>

      <ToolList enabled={props.tools} onToggle={props.onToggleTool} />
      <FileList files={props.files} onAdd={props.onAddFile} onRemove={props.onRemoveFile} />
    </div>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Seconds as a short clock reading, such as "48s" or "2m 05s". */
export function formatSeconds(seconds: number) {
  const whole = Math.max(0, Math.round(seconds));
  if (whole < 60) return `${whole}s`;
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  if (minutes < 60) return `${minutes}m ${String(rest).padStart(2, "0")}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`;
}

/** A token count, such as "840" or "12.4K". */
export const formatTokens = (value: number) => (value < 1000 ? WHOLE.format(Math.round(value)) : COMPACT.format(value));

/** A cost with cents, such as "$0.42". */
export const formatCost = (value: number) => CENTS.format(value);

/** A whole number with separators. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** Roll formats for `NumberTicker`. Module constants, because the ticker memoises its formatter on them. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

import type { AppId } from "../parts/app-mark";

/** A model the agent can run on. */
export interface BuilderModel {
  id: string;
  name: string;
  /** What the model is good for, in a few words. */
  line: string;
}

/** The invented models a Fernhill agent can run on. */
export const MODELS: BuilderModel[] = [
  { id: "larch-2", name: "Larch 2", line: "Careful answers, every conversation" },
  { id: "larch-2-mini", name: "Larch 2 mini", line: "Quick replies at a lower cost" },
  { id: "larch-3-preview", name: "Larch 3 preview", line: "Longer reasoning, still in preview" },
];

/** One tool the agent may use. */
export interface BuilderTool {
  id: "diary" | "records" | "inbox" | "ledger" | "chat";
  app: AppId;
  name: string;
  /** What the agent does with the tool. */
  line: string;
}

/** The tools on offer, in the order the list shows them. */
export const TOOLS: BuilderTool[] = [
  { id: "diary", app: "diary", name: "Fernhill Diary", line: "Find free slots and move bookings" },
  { id: "records", app: "records", name: "Patient records", line: "Read contact details and visit history" },
  { id: "inbox", app: "inbox", name: "Front desk inbox", line: "Read and draft replies to patients" },
  { id: "ledger", app: "ledger", name: "Ledger", line: "Look up deposits and refunds" },
  { id: "chat", app: "chat", name: "Team chat", line: "Hand a case to the front desk" },
];

/** A tool id. */
export type ToolId = BuilderTool["id"];

/** A knowledge file. `progress` runs from 0 to 100; 100 means the agent can read it. */
export interface BuilderFile {
  id: string;
  name: string;
  /** Size in kilobytes. */
  size: number;
  progress: number;
}

/** The files the agent starts with. */
export const FILES: BuilderFile[] = [
  { id: "policy", name: "Cancellation policy.pdf", size: 184, progress: 100 },
  { id: "hours", name: "Opening hours by clinic.csv", size: 12, progress: 100 },
];

/** Files a person can add, one per click, in turn. */
export const NEXT_FILES: Omit<BuilderFile, "progress">[] = [
  { id: "prices", name: "Visit prices 2026.pdf", size: 96 },
  { id: "rooms", name: "Room setup guide.docx", size: 340 },
  { id: "faq", name: "Front desk questions.md", size: 28 },
];

/** The instructions the agent starts with. */
export const INSTRUCTIONS =
  "You help patients of Fernhill clinics book, move and cancel visits. Check the diary before you offer a time. Quote the cancellation policy when a patient cancels within 24 hours. Never give medical advice: hand clinical questions to the front desk in team chat. Keep replies short and warm.";

/** The longest the instructions may be. */
export const INSTRUCTIONS_LIMIT = 2000;

/** A canned answer for the test chat. The agent picks the first whose words match the question. */
export interface TestAnswer {
  words: string[];
  /** The tool the answer needs. With the tool off, the agent says it cannot reach it. */
  tool: ToolId | null;
  reply: string;
}

/** The test chat's answers, checked in order. */
export const ANSWERS: TestAnswer[] = [
  {
    words: ["move", "reschedule", "change", "slot", "free", "book"],
    tool: "diary",
    reply: "Harbour Street has two free slots with Dr Okafor on Thursday: 9:40 and 14:20. Shall I move your visit to one of them?",
  },
  {
    words: ["cancel", "refund", "deposit", "fee"],
    tool: "ledger",
    reply: "Your 25 dollar deposit for Friday is refundable, since the visit is more than 24 hours away. I can cancel it and start the refund now.",
  },
  {
    words: ["open", "hours", "close", "weekend", "saturday"],
    tool: null,
    reply: "Mill Lane opens 8:00 to 18:00 on weekdays and 9:00 to 13:00 on Saturday. It is closed on Sunday.",
  },
  {
    words: ["pain", "medicine", "dose", "symptom", "hurt"],
    tool: "chat",
    reply: "I cannot give medical advice. I have passed your question to the front desk, and a nurse will call you back today.",
  },
];

/** The answer when no canned answer matches. */
export const FALLBACK_REPLY = "I can help you book, move or cancel a visit, or tell you when a clinic is open. What would you like to do?";

/** Questions a person can send with one click. */
export const SUGGESTIONS = ["Can I move my visit to Thursday?", "Can I get my deposit back?", "Is Mill Lane open on Saturday?"];

"use client";

import type { ReactNode, SVGProps } from "react";

import { CalendarIcon, MessageIcon, UsersIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { DatabaseIcon, FolderIcon, MailIcon, NotebookIcon, WalletIcon } from "../icons";

/** The invented apps a Fernhill agent can reach. Each one has its own hue and glyph. */
export type AppId = "diary" | "inbox" | "records" | "rota" | "ledger" | "files" | "notes" | "chat";

/** The name a person reads for each invented app. */
export const APP_NAME = {
  diary: "Fernhill Diary",
  inbox: "Front desk inbox",
  records: "Patient records",
  rota: "Staff rota",
  ledger: "Ledger",
  files: "Shared files",
  notes: "Visit notes",
  chat: "Team chat",
} satisfies Record<AppId, string>;

const APP_LOOK = {
  diary: { Icon: CalendarIcon, fill: "bg-chart-1" },
  inbox: { Icon: MailIcon, fill: "bg-chart-2" },
  records: { Icon: DatabaseIcon, fill: "bg-chart-3" },
  rota: { Icon: UsersIcon, fill: "bg-chart-4" },
  ledger: { Icon: WalletIcon, fill: "bg-chart-5" },
  files: { Icon: FolderIcon, fill: "bg-chart-2" },
  notes: { Icon: NotebookIcon, fill: "bg-chart-3" },
  chat: { Icon: MessageIcon, fill: "bg-chart-1" },
} satisfies Record<AppId, { Icon: (props: SVGProps<SVGSVGElement>) => ReactNode; fill: string }>;

/** Props for an app mark. */
export interface AppMarkProps {
  app: AppId;
  /** `sm` is 1.25rem, `md` is 1.75rem. */
  size?: "sm" | "md";
  className?: string;
}

/** A small coloured tile with the app's glyph. Decorative: the app name always sits beside it or in its label. */
export function AppMark({ app, size = "sm", className }: AppMarkProps) {
  const { Icon, fill } = APP_LOOK[app];
  return (
    <span
      aria-hidden="true"
      className={cn(
        "inline-flex shrink-0 items-center justify-center text-background",
        size === "sm" ? "size-5 rounded-md" : "size-7 rounded-lg",
        fill,
        className,
      )}
    >
      <Icon className={size === "sm" ? "size-3" : "size-4"} />
    </span>
  );
}

