/** Props for the knowledge files. */
export interface FileListProps {
  files: BuilderFile[];
  /** Null when every sample file is already added. */
  onAdd: (() => void) | null;
  onRemove: (id: string) => void;
}

/**
 * The files the agent can read. A file still uploading shows a bar and its
 * percent; a ready file shows its size. Each file has a remove button.
 */
export function FileList({ files, onAdd, onRemove }: FileListProps) {
  const id = useId();
  return (
    <section aria-labelledby={id} className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-3">
        <h3 id={id} className="text-sm font-medium">
          Knowledge
        </h3>
        <Button variant="outline" size="sm" onClick={onAdd ?? undefined} disabled={!onAdd}>
          <UploadIcon className="size-4" />
          Add file
        </Button>
      </div>
      {files.length === 0 ? (
        <p className="rounded-lg border border-dashed border-border px-3 py-4 text-center text-sm text-muted-foreground">
          No files yet. The agent answers from its instructions only.
        </p>
      ) : (
        <ul className="flex flex-col gap-1.5">
          {files.map((file) => {
            const done = file.progress >= 100;
            return (
              <li key={file.id} className="flex items-center gap-3 rounded-lg border border-border px-3 py-2">
                <FileIcon className="size-4 shrink-0 text-chart-2" />
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                  <span className="truncate text-sm">{file.name}</span>
                  {done ? (
                    <span className="text-xs text-muted-foreground">{formatCount(file.size)} KB</span>
                  ) : (
                    <span className="flex items-center gap-2">
                      <span
                        role="progressbar"
                        aria-label={`Uploading ${file.name}`}
                        aria-valuenow={Math.round(file.progress)}
                        aria-valuemin={0}
                        aria-valuemax={100}
                        className="h-1 flex-1 overflow-hidden rounded-full bg-muted"
                      >
                        <span
                          className="block h-full rounded-full bg-chart-2 w-(--w) motion-safe:transition-all motion-safe:duration-200"
                          style={
                            // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                            { "--w": `${file.progress}%` } as VarStyle
                          }
                        />
                      </span>
                      <span className="w-8 text-right text-xs text-muted-foreground tabular-nums">{Math.round(file.progress)}%</span>
                    </span>
                  )}
                </div>
                <Button variant="ghost" size="icon" aria-label={`Remove ${file.name}`} onClick={() => onRemove(file.id)} className="size-7">
                  <TrashIcon className="size-3.5" />
                </Button>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

