import { useId } from "react";

import { Switch } from "@/components/motion/switch";

import { AppMark } from "../parts/app-mark";
import { TOOLS, type ToolId } from "./data";

/** Props for the tool switches. */
export interface ToolListProps {
  enabled: Set<ToolId>;
  onToggle: (tool: ToolId, on: boolean) => void;
}

/** Each tool the agent may use, with its app mark, what it does and a switch. A count heads the list. */
export function ToolList({ enabled, onToggle }: ToolListProps) {
  const id = useId();
  return (
    <section aria-labelledby={`${id}-title`} className="flex flex-col gap-2">
      <div className="flex items-baseline justify-between gap-3">
        <h3 id={`${id}-title`} className="text-sm font-medium">
          Tools
        </h3>
        <span aria-live="polite" className="text-xs text-muted-foreground tabular-nums">
          {enabled.size} of {TOOLS.length} on
        </span>
      </div>
      <ul className="flex flex-col">
        {TOOLS.map((tool) => {
          const on = enabled.has(tool.id);
          const switchId = `${id}-${tool.id}`;
          return (
            <li key={tool.id} className="flex items-center gap-3 border-t border-border py-2.5 first:border-t-0">
              <AppMark app={tool.app} className={on ? undefined : "opacity-40"} />
              <label htmlFor={switchId} className="flex min-w-0 flex-1 cursor-pointer flex-col">
                <span className="truncate text-sm">{tool.name}</span>
                <span className="truncate text-xs text-muted-foreground">{tool.line}</span>
              </label>
              <Switch id={switchId} checked={on} onCheckedChange={(next) => onToggle(tool.id, next)} />
            </li>
          );
        })}
      </ul>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { PencilIcon } from "../icons";

/** Props for the agent's editable name. */
export interface NameFieldProps {
  name: string;
  onRename: (name: string) => void;
  /** The id of the heading, so the card can name itself after the agent. */
  headingId: string;
}

/**
 * The agent's name as a heading with an edit button. Editing swaps in a text
 * field: Enter or leaving the field saves, Escape puts the old name back.
 */
export function NameField({ name, onRename, headingId }: NameFieldProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(name);
  const field = useRef<HTMLInputElement>(null);
  const editButton = useRef<HTMLButtonElement>(null);
  const returnFocus = useRef(false);

  useEffect(() => {
    if (editing) field.current?.select();
    else if (returnFocus.current) {
      returnFocus.current = false;
      editButton.current?.focus();
    }
  }, [editing]);

  const finish = (save: boolean) => {
    const clean = draft.trim();
    if (save && clean && clean !== name) onRename(clean);
    else setDraft(name);
    returnFocus.current = true;
    setEditing(false);
  };

  if (editing) {
    return (
      <Input
        ref={field}
        aria-label="Agent name"
        value={draft}
        maxLength={40}
        onChange={(event) => setDraft(event.target.value)}
        onBlur={() => finish(true)}
        onKeyDown={(event) => {
          if (event.nativeEvent.isComposing || event.keyCode === 229) return;
          if (event.key === "Enter") {
            event.preventDefault();
            finish(true);
          } else if (event.key === "Escape") {
            event.preventDefault();
            finish(false);
          }
        }}
        className="-mx-3 h-8 w-full max-w-64"
      />
    );
  }

  return (
    <div className="flex min-w-0 items-center gap-1">
      <h2 id={headingId} className="truncate text-base font-semibold">
        {name}
      </h2>
      <Button
        ref={editButton}
        variant="ghost"
        size="icon"
        aria-label={`Rename ${name}`}
        onClick={() => {
          setDraft(name);
          setEditing(true);
        }}
        className="size-7"
      >
        <PencilIcon className="size-3.5" />
      </Button>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { type FormEvent, useEffect, useId, useRef, useState } from "react";

import { ArrowUpIcon, SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { useInterval } from "../lib/timers";
import { AppMark } from "../parts/app-mark";
import {
  ANSWERS,
  FALLBACK_REPLY,
  SUGGESTIONS,
  TOOLS,
  type BuilderTool,
  type ToolId,
} from "./data";

interface Message {
  id: number;
  from: "person" | "agent";
  text: string;
  /** How many words of an agent reply show so far. */
  shown: number;
  /** The tool the reply used. */
  tool?: BuilderTool;
}

/** Props for the test chat. */
export interface TestChatProps {
  agentName: string;
  tools: Set<ToolId>;
}

/** A reply and the tool it used, if any. */
interface Reply {
  text: string;
  tool?: BuilderTool;
}

/** Picks the reply for a question from the canned answers, given the tools that are on. */
function answerFor(question: string, tools: Set<ToolId>): Reply {
  const lower = question.toLowerCase();
  const match = ANSWERS.find((answer) =>
    answer.words.some((word) => lower.includes(word)),
  );
  if (!match) return { text: FALLBACK_REPLY };
  if (!match.tool) return { text: match.reply };
  const tool = TOOLS.find((item) => item.id === match.tool)!;
  if (!tools.has(match.tool)) {
    return {
      text: `I need ${tool.name} to answer that, and it is turned off for me. Turn it on in Configure and ask again.`,
    };
  }
  return { text: match.reply, tool };
}

/**
 * A small chat that answers with the tools that are on. A reply streams in
 * word by word, names the tool it used, and is marked with sparkles. With a
 * tool off, the agent says it cannot reach it.
 */
export function TestChat({ agentName, tools }: TestChatProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [announce, setAnnounce] = useState("");
  const [waiting, setWaiting] = useState(false);
  const reduceMotion = useReducedMotion();
  const nextId = useRef(1);
  const pending = useRef<number | null>(null);
  const scroller = useRef<HTMLDivElement>(null);
  const inputId = useId();

  const streaming = messages.find(
    (message) =>
      message.from === "agent" && message.shown < wordCount(message.text),
  );

  useInterval(
    () => {
      if (!streaming) return;
      const shown = streaming.shown + 2;
      if (shown >= wordCount(streaming.text))
        setAnnounce(`${agentName}: ${streaming.text}`);
      setMessages((list) =>
        list.map((message) =>
          message.id === streaming.id ? { ...message, shown } : message,
        ),
      );
    },
    streaming ? 45 : null,
  );

  useEffect(
    () => () => {
      if (pending.current !== null) window.clearTimeout(pending.current);
    },
    [],
  );

  useEffect(() => {
    const box = scroller.current;
    if (box) box.scrollTop = box.scrollHeight;
  }, [messages]);

  const ask = (question: string) => {
    const text = question.trim();
    if (!text || streaming || waiting) return;
    setMessages((list) => [
      ...list,
      { id: nextId.current++, from: "person", text, shown: 0 },
    ]);
    setDraft("");
    setWaiting(true);
    const reply = answerFor(text, tools);
    pending.current = window.setTimeout(() => {
      pending.current = null;
      setWaiting(false);
      const full = wordCount(reply.text);
      if (reduceMotion) setAnnounce(`${agentName}: ${reply.text}`);
      setMessages((list) => [
        ...list,
        {
          id: nextId.current++,
          from: "agent",
          text: reply.text,
          tool: reply.tool,
          shown: reduceMotion ? full : 0,
        },
      ]);
    }, 450);
  };

  const onSubmit = (event: FormEvent) => {
    event.preventDefault();
    ask(draft);
  };

  const busy = Boolean(streaming) || waiting;

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div
        ref={scroller}
        className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto scroll-fade-effect-y scrollbar-none p-5"
      >
        {messages.length === 0 ? (
          <div className="m-auto flex max-w-xs flex-col items-center gap-3 text-center">
            <SparklesIcon aria-hidden="true" className="size-5 text-chart-4" />
            <p className="text-sm text-muted-foreground">
              Ask {agentName} what a patient would ask. It answers with the
              tools that are on.
            </p>
            <ul className="flex flex-col items-center gap-2">
              {SUGGESTIONS.map((suggestion) => (
                <li key={suggestion}>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => ask(suggestion)}
                  >
                    {suggestion}
                  </Button>
                </li>
              ))}
            </ul>
          </div>
        ) : (
          <ol
            aria-label={`Test conversation with ${agentName}`}
            className="flex flex-col gap-3"
          >
            {messages.map((message) => (
              <ChatMessage key={message.id} message={message} />
            ))}
          </ol>
        )}
      </div>
      <p aria-live="polite" className="sr-only">
        {announce}
      </p>
      <form
        onSubmit={onSubmit}
        className="flex items-center gap-2 border-t border-border p-3"
      >
        <label htmlFor={inputId} className="sr-only">
          Message {agentName}
        </label>
        <Input
          id={inputId}
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Ask as a patient would"
          autoComplete="off"
        />
        <Button
          type="submit"
          size="icon"
          aria-label="Send"
          disabled={!draft.trim() || busy}
        >
          <ArrowUpIcon className="size-4" />
        </Button>
      </form>
    </div>
  );
}

function wordCount(text: string) {
  return text.split(" ").length;
}

/** One message: a person's question on the right, an agent reply on the left with sparkles and the tool it used. */
function ChatMessage({ message }: { message: Message }) {
  if (message.from === "person") {
    return (
      <li className="max-w-[85%] self-end rounded-2xl rounded-br-md bg-primary px-3 py-2 text-sm text-primary-foreground">
        {message.text}
      </li>
    );
  }
  const words = message.text.split(" ");
  const done = message.shown >= words.length;
  return (
    <li className="flex max-w-[90%] gap-2 self-start">
      {/* A box one text line tall centres the icon on the first line, with no nudge. */}
      <span className="flex h-5 shrink-0 items-center">
        <SparklesIcon
          aria-hidden="true"
          className="size-4 shrink-0 text-chart-4"
        />
      </span>
      <div className="flex min-w-0 flex-col gap-1.5">
        <p
          className={cn(
            "rounded-2xl rounded-bl-md border border-border px-3 py-2 text-sm",
            done
              ? null
              : "motion-safe:after:animate-pulse after:content-['_▍']",
          )}
        >
          <span className="sr-only">Agent: </span>
          {words.slice(0, Math.max(1, message.shown)).join(" ")}
        </p>
        {message.tool && done ? (
          <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <AppMark app={message.tool.app} className="size-4 rounded" />
            Used {message.tool.name}
          </span>
        ) : null}
      </div>
    </li>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Calls `callback` every `delay` milliseconds while `delay` is a number, and
 * stops when it is null or the component unmounts. The latest callback always runs.
 */
export function useInterval(callback: () => void, delay: number | null) {
  const saved = useRef(callback);
  useEffect(() => {
    saved.current = callback;
  }, [callback]);
  useEffect(() => {
    if (delay === null) return;
    const id = window.setInterval(() => saved.current(), delay);
    return () => window.clearInterval(id);
  }, [delay]);
}

/**
 * Whole seconds since `running` last turned true. The count holds while
 * `running` is false and starts again from zero on `resetKey` change.
 */
export function useElapsed(running: boolean, resetKey: string | number = 0) {
  const [state, setState] = useState({ key: resetKey, seconds: 0 });
  // A new reset key starts the count again, adjusted during render rather than in an effect.
  if (state.key !== resetKey) setState({ key: resetKey, seconds: 0 });
  useInterval(() => setState((current) => ({ ...current, seconds: current.seconds + 1 })), running ? 1000 : null);
  return state.key === resetKey ? state.seconds : 0;
}

/**
 * Runs a list of timed steps one after another. Each step waits its `after`
 * milliseconds, then calls `run`. Every pending timer clears on unmount or when `key` changes.
 */
export function useSchedule(steps: { after: number; run: () => void }[] | null, key: string | number) {
  const saved = useRef(steps);
  useEffect(() => {
    saved.current = steps;
  });
  useEffect(() => {
    const list = saved.current;
    if (!list) return;
    const ids: number[] = [];
    let total = 0;
    for (const step of list) {
      total += step.after;
      ids.push(window.setTimeout(step.run, total));
    }
    return () => ids.forEach((id) => window.clearTimeout(id));
  }, [key]);
}
